package com.termux.app.workspace;

import android.app.Activity;
import android.app.AlertDialog;
import android.os.Environment;
import android.view.View;
import android.widget.*;
import com.termux.app.TermuxActivity;
import org.json.*;
import java.io.File;
import java.util.*;
import java.util.function.Consumer;

/** Deliberate backup/restore flows. No operation runs merely from opening settings. */
final class WorkspaceBackupUi {
    private final TermuxActivity activity;private final WorkspaceStore store;private final Runnable changed;private final Consumer<String> packageInstall;
    private WorkspaceBackupUi(TermuxActivity a,WorkspaceStore s,Runnable r,Consumer<String> install){activity=a;store=s;changed=r;packageInstall=install;}
    static String text(Activity a,String ru,String en){return WorkspaceLanguage.code(a).equals("ru")?ru:en;}
    private String t(String ru,String en){return text(activity,ru,en);}
    static String label(Activity a){return text(a,"Резервное копирование · бета","Backup and restore · beta");}
    static void show(TermuxActivity a,WorkspaceStore s,Runnable changed,Consumer<String> install){new WorkspaceBackupUi(a,s,changed,install).menu();}
    private void message(String text){if(!activity.isDestroyed())WorkspaceDialogs.builder(activity).setTitle(label(activity)).setMessage(text).setPositiveButton("OK",null).show();}
    private LinearLayout column(){LinearLayout v=new LinearLayout(activity);v.setOrientation(1);int d=WorkspaceDialogs.dp(activity,16);v.setPadding(d,d,d,d);return v;}
    private void info(LinearLayout form,String value){TextView v=new TextView(activity);v.setText(value);v.setTextColor(WorkspaceDialogs.TEXT);v.setTextSize(14);v.setPadding(0,8,0,12);form.addView(v);}
    private CheckBox check(LinearLayout form,String value,boolean selected){CheckBox b=new CheckBox(activity);b.setText(value);b.setTextColor(WorkspaceDialogs.TEXT);b.setChecked(selected);form.addView(b);return b;}
    private EditText field(LinearLayout form,String value,String hint){EditText e=new EditText(activity);e.setSingleLine();e.setText(value);e.setHint(hint);e.setTextColor(WorkspaceDialogs.TEXT);e.setSelectAllOnFocus(true);form.addView(e);return e;}
    private void action(LinearLayout form,String title,Runnable click){TextView b=WorkspaceDialogs.action(activity,title,0);b.setOnClickListener(v->click.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=WorkspaceDialogs.dp(activity,8);form.addView(b,p);}
    private ScrollView scroll(LinearLayout form){ScrollView s=new ScrollView(activity);s.setFillViewport(false);s.addView(form);return s;}
    private void menu(){WorkspaceDialogs.builder(activity).setTitle(label(activity)).setItems(new String[]{t("Создать резервную копию","Create backup"),t("Проверить резервную копию","Verify backup"),t("Восстановить из файла","Restore from file")},(d,w)->{if(w==0)inventory();else chooseFile(w==2);}).setNegativeButton(WorkspaceText.tr("Закрыть"),null).show();}
    private void run(JSONObject request,Consumer<JSONObject> success){
        WorkspaceBackupEngine engine=new WorkspaceBackupEngine();AlertDialog dialog=WorkspaceDialogs.builder(activity).setTitle(label(activity)).setMessage(t("Подготовка…","Preparing…")).setNegativeButton(WorkspaceText.tr("Отмена"),(d,w)->engine.cancel()).create();dialog.setOnCancelListener(d->engine.cancel());
        boolean started=engine.start(activity,request,new WorkspaceBackupEngine.Callback(){
            public void progress(String stage,long value){if(dialog.isShowing())dialog.setMessage(stageName(stage)+(value>0?" · "+android.text.format.Formatter.formatFileSize(activity,value):""));}
            public void done(JSONObject result){dialog.dismiss();try{success.accept(result);}catch(Exception e){message(t("Операция не применена полностью. Проверьте результат и сохранённые исходные данные.","Operation was not fully applied. Inspect the result; original files were retained."));}}
            public void error(String code){dialog.dismiss();message(errorText(code));}
        });if(started)dialog.show();else message(t("Другая операция резервного копирования ещё выполняется.","Another backup operation is still running."));
    }
    private String stageName(String stage){switch(stage){case "CHECKSUM":return t("Проверка SHA-256","Checking SHA-256");case "SCAN":return t("Проверка структуры архива","Checking archive structure");case "VERIFY_COMPRESSION":return t("Проверка целостности сжатия","Verifying compressed stream");case "ARCHIVE":return t("Создание архива","Creating archive");case "PROOT_DISTRO":return t("Работа proot-distro","Running proot-distro");case "RESTORE_FILES":return t("Извлечение в новую папку","Extracting to a new folder");case "PREPARE_UBUNTU":return t("Подготовка отдельной Ubuntu","Preparing separate Ubuntu");default:return t("Подготовка и оценка размера","Preparing and estimating size");}}
    private String errorText(String code){switch(code){case "PYTHON_REQUIRED":return t("Нужен Python в Termux. Установите вручную: pkg install python. Данные не изменены.","Python is required in Termux. Install manually: pkg install python. Your data was not changed.");case "INSUFFICIENT_SPACE":return t("Недостаточно свободного места. Для восстановления нужен запас на проверенную копию и извлечение.","Not enough free space. Restore needs room for a verified copy and extraction.");case "CANCELLED":return t("Операция отменена. Незавершённая копия помечена INCOMPLETE, если каталог уже был создан. Не используйте её как готовый бэкап.","Cancelled. A created partial backup/restore folder is marked INCOMPLETE. Do not treat it as complete.");case "ARCH_OR_PROOT_UNCONFIRMED":return t("Архитектура не подтверждена/несовместима или нужен современный proot-distro. Восстановление Ubuntu заблокировано.","Architecture is unconfirmed/incompatible or modern proot-distro is required. Ubuntu restore blocked.");case "UNRECOGNIZED_ARCHIVE":return t("Формат архива не распознан. Поддерживаются manifest.json нашего бэкапа, workspace-v1.json и распознаваемые TAR-архивы HOME/PREFIX/proot-distro.","Archive format not recognized. Supported: our manifest.json, workspace-v1.json and recognized HOME/PREFIX/proot-distro TAR layouts.");case "UNSAFE_ARCHIVE_PATH":case "WRITE_THROUGH_SYMLINK":case "UNSAFE_LINK":case "DUPLICATE_ARCHIVE_PATH":return t("Архив содержит опасные или конфликтующие пути/ссылки. Восстановление заблокировано.","Archive contains unsafe or conflicting paths/links. Restore blocked.");case "CHECKSUM_MISMATCH":case "BACKUP_CHANGED_RECHECK":return t("Контрольная сумма не совпадает или бэкап изменился. Выберите и проверьте его заново.","Checksum mismatch or backup changed. Select and verify it again.");default:return t("Операция остановлена. Текущие окружения не заменялись. Возможна нехватка прав, повреждённый/неподдерживаемый архив или ошибка инструмента. Код: ","Operation stopped. Existing environments were not replaced. Check permissions, archive format/integrity and required tools. Code: ")+code;}}
    private JSONObject request(String operation){try{return WorkspaceBackupEngine.base(activity,operation);}catch(Exception e){throw new IllegalStateException(e);}}
    private void inventory(){run(request("inventory"),this::createForm);}
    private void createForm(JSONObject inventory){try{
        LinearLayout form=column();info(form,t("Бета. Архивы могут содержать SSH-ключи, токены и авторизацию. Завершите изменяющие файлы задачи перед копированием. Процессы не останавливаются автоматически; копия работающих баз не гарантированно согласована.","Beta. Archives may contain SSH keys, tokens and authorization. Finish file-writing tasks first. Processes are not stopped automatically; live database copies may be inconsistent."));
        CheckBox library=check(form,t("Команды, заметки, пресеты, настройки и файлы истории сессий","Commands, notes, presets, settings and shell history files"),true);
        if(!store.isWritable()){library.setChecked(false);library.setEnabled(false);info(form,t("Библиотека недоступна для чтения/записи. Её исходный файл нужно сохранить отдельно.","Library is unavailable. Preserve its original file separately."));}
        CheckBox home=check(form,"Termux HOME · "+size(inventory.optLong("homeBytes")),false),prefix=check(form,"Termux PREFIX · "+size(inventory.optLong("prefixBytes")),false);
        info(form,t("PREFIX сохраняется без rootfs/cache proot-distro и временных файлов. Ubuntu выбирается отдельно. Внешние файлы по символьным ссылкам и общая память Android не копируются.","PREFIX excludes proot-distro storage/cache and temporary files. Select Ubuntu separately. External symlink targets and Android shared storage are not copied."));
        JSONArray environments=inventory.getJSONArray("environments");List<CheckBox> envChecks=new ArrayList<>();for(int i=0;i<environments.length();i++){String name=environments.getJSONObject(i).getString("name");envChecks.add(check(form,"Ubuntu / proot · "+name+" · "+size(inventory.getJSONObject("ubuntuBytes").optLong(name)),false));}
        EditText destination=field(form,Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS).getAbsolutePath(),t("Каталог для нового бэкапа","Directory for a new backup"));action(form,t("Выбрать каталог","Choose directory"),()->browse(new File(destination.getText().toString()),true,p->destination.setText(p)));
        CheckBox confirmed=check(form,t("Я завершил важные задачи и понимаю, что архив содержит секреты","I finished important jobs and understand the archive contains secrets"),false);
        AlertDialog dialog=WorkspaceDialogs.builder(activity).setTitle(t("Создать резервную копию","Create backup")).setView(scroll(form)).setPositiveButton(t("Создать","Create"),null).setNegativeButton(WorkspaceText.tr("Отмена"),null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{
            if(!confirmed.isChecked()){confirmed.setError(t("Нужно подтверждение","Confirmation required"));return;}JSONArray selected=new JSONArray(),envs=new JSONArray();if(library.isChecked())selected.put("library");if(home.isChecked())selected.put("home");if(prefix.isChecked())selected.put("prefix");for(int i=0;i<envChecks.size();i++)if(envChecks.get(i).isChecked())envs.put(environments.getJSONObject(i).getString("name"));if(selected.length()+envs.length()==0)return;
            JSONObject req=request("create").put("destination",destination.getText().toString().trim()).put("components",selected).put("environments",envs).put("workspace",store.encode()).put("settings",WorkspaceBackupImport.settings(activity));dialog.dismiss();run(req,result->message(t("Бэкап создан и проверен.\n","Backup created and verified.\n")+result.optString("path")+"\n"+size(result.optLong("bytes"))+"\n"+t("Сохраните весь каталог. Скрипт restore.sh и инструкция находятся внутри. Это не проверка реального восстановления.","Keep the entire directory. restore.sh and instructions are inside. This does not establish real-device restore success.")));
        }catch(Exception e){message(t("Не удалось подготовить бэкап.","Could not prepare backup."));}}));dialog.show();
    }catch(Exception e){message(errorText("INVENTORY_FAILED"));}}
    private String size(long value){return android.text.format.Formatter.formatFileSize(activity,value);}
    private void chooseFile(boolean restore){LinearLayout form=column();info(form,t("Выберите manifest.json из каталога бэкапа, workspace-v1.json или TAR-архив. Проверка ничего не распаковывает и не запускает.","Choose manifest.json from a backup directory, workspace-v1.json or a TAR archive. Inspection never extracts or executes archive contents."));EditText file=field(form,Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS).getAbsolutePath(),t("Путь к файлу","File path"));action(form,t("Выбрать файл","Choose file"),()->browse(new File(file.getText().toString()),false,file::setText));WorkspaceDialogs.builder(activity).setTitle(restore?t("Восстановить из файла","Restore from file"):t("Проверить резервную копию","Verify backup")).setView(scroll(form)).setPositiveButton(t("Проверить","Verify"),(d,w)->{try{run(request("inspect").put("path",file.getText().toString().trim()),r->report(r,restore));}catch(Exception e){message(errorText("INVALID_PATH"));}}).setNegativeButton(WorkspaceText.tr("Отмена"),null).show();}
    private void browse(File start,boolean folders,Consumer<String> selected){
        File folder=start.isDirectory()?start:start.getParentFile();if(folder==null||!folder.isDirectory())folder=Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS);
        File[] list=folder.listFiles(f->!WorkspaceBackupEngine.symlink(f)&&(f.isDirectory()||!folders&&f.isFile()));if(list==null){message(t("Нет доступа к папке. Проверьте разрешение доступа к файлам Android или введите доступный путь вручную.","Cannot access this directory. Check Android storage permission or enter an accessible path."));return;}Arrays.sort(list,Comparator.comparing((File f)->!f.isDirectory()).thenComparing(File::getName));if(list.length>3000){message(t("Слишком много файлов; введите вложенный путь.","Too many files; enter a nested path."));return;}List<String> rows=new ArrayList<>();rows.add("../");for(File f:list)rows.add((f.isDirectory()?"▸ ":"")+f.getName());File current=folder;
        AlertDialog.Builder b=WorkspaceDialogs.builder(activity).setTitle(current.getAbsolutePath()).setItems(rows.toArray(new String[0]),(d,w)->{if(w==0){File parent=current.getParentFile();if(parent!=null)browse(parent,folders,selected);}else if(list[w-1].isDirectory())browse(list[w-1],folders,selected);else selected.accept(list[w-1].getAbsolutePath());}).setNegativeButton(WorkspaceText.tr("Отмена"),null);if(folders)b.setPositiveButton(t("Выбрать эту папку","Select this directory"),(d,w)->selected.accept(current.getAbsolutePath()));b.show();
    }
    private void report(JSONObject report,boolean restore){try{
        LinearLayout form=column();info(form,t("Проверка завершена. SHA-256 не подтверждает подлинность чужого бэкапа. Не восстанавливайте недоверенные данные. Совместимость работающих баз и внешних путей автоматически не гарантируется.","Inspection complete. SHA-256 does not authenticate a foreign backup. Do not restore untrusted data. Live database consistency and external paths are not guaranteed."));
        JSONObject source=report.optJSONObject("source");if(source!=null&&source.length()>0)info(form,t("Источник: ","Source: ")+source.optString("packageId","?")+" · "+source.optString("arch","?")+" · "+source.optString("appVersion","?")+"\n"+t("Пути из бэкапа: ","Backup paths: ")+source.optString("home","?")+" / "+source.optString("prefix","?"));else info(form,t("Исходные версии приложения и package ID неизвестны. Совместимость путей не подтверждена.","Source app version and package ID are unknown. Path compatibility is unconfirmed."));
        JSONArray components=report.getJSONArray("components");for(int i=0;i<components.length();i++){JSONObject c=components.getJSONObject(i);info(form,(i+1)+". "+kindName(c.optString("kind"))+" · "+c.optString("format")+" · "+c.optString("arch")+"\n"+status(c)+" · "+size(c.optLong("unpacked")));}
        JSONObject library=report.optJSONObject("workspace");if(library!=null)info(form,t("Библиотека: команды / заметки / пресеты: ","Library: commands / notes / presets: ")+count(library,"commands")+" / "+count(library,"notes")+" / "+count(library,"sessions"));info(form,t("Свободно: ","Free: ")+size(report.optLong("free")));
        action(form,t("Пакеты · сравнить версии","Packages · compare versions"),()->packages(report));
        action(form,t("Выбрать компоненты восстановления","Choose restore components"),()->restoreForm(report));
        WorkspaceDialogs.builder(activity).setTitle(t("Проверка бэкапа · бета","Backup inspection · beta")).setView(scroll(form)).setPositiveButton(WorkspaceText.tr("Закрыть"),null).show();
    }catch(Exception e){message(errorText("REPORT_FAILED"));}}
    private static int count(JSONObject v,String key){JSONArray a=v.optJSONArray(key);return a==null?0:a.length();}
    private String kindName(String kind){switch(kind){case "home":return "Termux HOME";case "prefix":return "Termux PREFIX";case "ubuntu":return "Ubuntu / proot";case "app-data":return t("Файлы истории терминала","Terminal history files");case "packages":return t("Список пакетов Termux","Termux package list");case "library":return t("Библиотека приложения","App library");default:return kind;}}
    private String status(JSONObject c){if(c.optString("status").equals("blocked"))return t("ЗАБЛОКИРОВАНО: архитектура или proot-distro не подтверждены","BLOCKED: architecture or proot-distro unconfirmed");if(c.optString("kind").equals("prefix"))return t("Только извлечение отдельно; текущий PREFIX не заменяется","Staging only; current PREFIX is not replaced");if(c.optString("kind").equals("ubuntu"))return t("Отдельная среда с новым именем","Separate environment with a fresh name");return t("Перенос в новую папку; пути требуют проверки","Stage in a new directory; review paths");}
    private void restoreForm(JSONObject report){try{
        LinearLayout form=column();info(form,t("Файлы извлекаются только в новую подпапку выбранного каталога HOME. Текущие HOME/PREFIX/Ubuntu не заменяются. Пресеты после импорта требуют проверки путей и среды перед запуском. Сохранённые пароли SSH Android Keystore перенести нельзя.","Files are staged only in a new subdirectory under HOME. Current HOME/PREFIX/Ubuntu are not replaced. Imported presets require path/environment review before launch. Android Keystore remembered SSH passwords cannot be transferred."));
        JSONArray components=report.getJSONArray("components");List<CheckBox> selected=new ArrayList<>();for(int i=0;i<components.length();i++){JSONObject c=components.getJSONObject(i);CheckBox b=check(form,kindName(c.optString("kind"))+" · "+status(c),false);b.setEnabled(!c.optString("status").equals("blocked"));selected.add(b);}
        WorkspaceBackupImport.Choice choice=new WorkspaceBackupImport.Choice();JSONObject library=report.optJSONObject("workspace");CheckBox commands=check(form,t("Импортировать команды","Import commands"),false),notes=check(form,t("Импортировать заметки","Import notes"),false),presets=check(form,t("Импортировать пресеты запуска","Import launch presets"),false),history=check(form,t("Перенести файлы истории импортируемых пресетов (нужен app-data)","Copy history files for imported presets (requires app-data)"),false),settings=check(form,t("Импортировать настройки приложения","Import app settings"),false),replace=check(form,t("Заменить выбранные библиотеки вместо объединения","Replace selected libraries instead of merging"),false);
        commands.setEnabled(library!=null);notes.setEnabled(library!=null);presets.setEnabled(library!=null);history.setEnabled(library!=null);settings.setEnabled(report.optJSONObject("settings")!=null);
        JSONArray candidates=report.optJSONArray("candidates");Set<Integer> chosen=new HashSet<>();action(form,t("Aliases и скрипты → добавить в команды","Aliases and scripts → add to commands"),()->candidatePicker(candidates,chosen));
        EditText dest=field(form,WorkspaceBackupEngine.home(),t("Родительский каталог внутри HOME","Parent directory inside HOME"));action(form,t("Выбрать каталог","Choose directory"),()->browse(new File(dest.getText().toString()),true,dest::setText));
        CheckBox agree=check(form,t("Я доверяю бэкапу и подтверждаю выбранный план","I trust this backup and confirm the selected plan"),false);
        AlertDialog dialog=WorkspaceDialogs.builder(activity).setTitle(t("План восстановления","Restore plan")).setView(scroll(form)).setPositiveButton(t("Подтвердить восстановление","Confirm restore"),null).setNegativeButton(WorkspaceText.tr("Отмена"),null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{
            if(!agree.isChecked()){agree.setError(t("Нужно подтверждение","Confirmation required"));return;}JSONArray indices=new JSONArray();for(int i=0;i<selected.size();i++)if(selected.get(i).isChecked())indices.put(i);choice.commands=commands.isChecked();choice.notes=notes.isChecked();choice.presets=presets.isChecked();choice.history=history.isChecked();choice.settings=settings.isChecked();choice.replace=replace.isChecked();choice.candidates=chosen;
            for(Integer index:chosen){JSONObject c=candidates.getJSONObject(index);if(c.getString("kind").equals("script")&&!selected.get(c.getInt("component")).isChecked()){message(t("Для выбранного скрипта сначала выберите восстановление его HOME/Ubuntu.","Select the HOME/Ubuntu component containing each chosen script."));return;}}
            if(indices.length()==0&&!choice.commands&&!choice.notes&&!choice.presets&&!choice.settings&&chosen.isEmpty())return;
            JSONObject req=request("inspect").put("path",report.getString("path"));dialog.dismiss();run(req,fresh->{try{if(!fresh.getJSONObject("fingerprints").toString().equals(report.getJSONObject("fingerprints").toString())){message(errorText("BACKUP_CHANGED_RECHECK"));return;}if(indices.length()==0)applyImport(fresh,new JSONObject(),choice);else run(request("restore").put("path",report.getString("path")).put("fingerprints",report.getJSONObject("fingerprints")).put("selected",indices).put("destination",dest.getText().toString().trim()),r->applyImport(fresh,r,choice));}catch(Exception e){message(errorText("IMPORT_FAILED"));}});
        }catch(Exception e){message(errorText("IMPORT_FAILED"));}}));dialog.show();
    }catch(Exception e){message(errorText("IMPORT_FAILED"));}}
    private void candidatePicker(JSONArray candidates,Set<Integer> selected){if(candidates==null||candidates.length()==0){message(t("Простые aliases и shell-скрипты не найдены.","No simple aliases or shell scripts found."));return;}String[] labels=new String[candidates.length()];boolean[] values=new boolean[labels.length];for(int i=0;i<labels.length;i++){JSONObject c=candidates.optJSONObject(i);labels[i]=c.optString("kind")+" · "+c.optString("name")+"\n"+c.optString("source");values[i]=selected.contains(i);}WorkspaceDialogs.builder(activity).setTitle(t("Добавить в команды","Add to commands")).setMultiChoiceItems(labels,values,(d,w,checked)->{if(checked)selected.add(w);else selected.remove(w);}).setPositiveButton("OK",null).show();}
    private void applyImport(JSONObject report,JSONObject restored,WorkspaceBackupImport.Choice choice){
        AlertDialog wait=WorkspaceDialogs.builder(activity).setTitle(label(activity)).setMessage(t("Проверка и импорт библиотеки…","Validating and importing library…")).create();wait.setCancelable(false);wait.show();
        new Thread(()->{try{WorkspaceBackupImport.Prepared prepared=WorkspaceBackupImport.prepare(activity,report,restored,choice);activity.runOnUiThread(()->{try{
            if(activity.isDestroyed())return;WorkspaceBackupImport.apply(activity,store,prepared,choice);if(choice.settings){WorkspaceBackupImport.settings(activity,report.optJSONObject("settings"));WorkspaceLanguage.apply(activity);}changed.run();
            new Thread(()->{try{store.awaitWrites();String saved=new String(readFile(new File(activity.getFilesDir(),"workspace-v1.json")),java.nio.charset.StandardCharsets.UTF_8);if(!WorkspaceBackupImport.persisted(new JSONObject(saved),prepared))throw new java.io.IOException();activity.runOnUiThread(()->{wait.dismiss();message(t("Выбранные компоненты восстановлены. Ничего из архива не запускалось. Проверьте пути, настройки и авторизацию. Для части настроек нужно заново открыть приложение.\n","Selected components restored. No archive content was executed. Review paths, settings and authorization. Some settings require reopening the app.\n")+restored.optString("path",t("Импортирована библиотека","Library imported"))+"\n"+t("Отдельные Ubuntu добавлены как пресеты запуска. Исходные библиотеки перед импортом сохранены в приватном каталоге приложения.","Separate Ubuntu environments were added as launch presets. Original libraries were saved in the app's private directory before import."));});}catch(Exception e){activity.runOnUiThread(()->{wait.dismiss();message(errorText("LIBRARY_WRITE_FAILED"));});}},"jobs-backup-save").start();
        }catch(Exception e){wait.dismiss();message(errorText("IMPORT_FAILED"));}});}catch(Exception e){activity.runOnUiThread(()->{wait.dismiss();message(t("Файлы могли быть извлечены, но импорт библиотеки не завершён. Проверьте каталог результата.","Files may have been staged, but library import did not complete. Inspect the result directory."));});}},"jobs-backup-import").start();
    }
    private byte[] readFile(File file)throws java.io.IOException{try(java.io.InputStream in=new java.io.FileInputStream(file);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] data=new byte[8192];int n;while((n=in.read(data))!=-1){if(out.size()+n>16*1024*1024)throw new java.io.IOException();out.write(data,0,n);}return out.toByteArray();}}
    private void packages(JSONObject report){JSONObject source=report.optJSONObject("packages");if(source==null||source.length()==0){message(t("Список пакетов Termux в бэкапе не найден. Пакеты отдельной Ubuntu восстанавливаются с её системой и с текущим Termux не смешиваются.","No Termux package list found. Separate Ubuntu packages are restored with its rootfs, not mixed into current Termux."));return;}try{run(request("packages").put("packages",source),r->{JSONArray rows=r.optJSONArray("packages");if(rows==null||rows.length()==0){message(t("Различий в известных версиях не найдено.","No differences in known package versions."));return;}packageSelection(rows);});}catch(Exception e){message(errorText("PACKAGE_LIST_FAILED"));}}
    private void packageSelection(JSONArray rows){Set<Integer> selected=new HashSet<>();LinearLayout form=column();info(form,t("Сравнение относится к пакетам Termux. Выбирайте только доверенные пакеты. APT может изменить зависимости; план показывается до установки. Текущие репозитории должны содержать выбранные версии.","Comparison covers Termux packages. Select trusted packages only. APT may change dependencies; review its plan before installing. Selected versions must exist in current repositories."));List<CheckBox> checks=new ArrayList<>();for(int i=0;i<rows.length();i++){JSONObject p=rows.optJSONObject(i);CheckBox b=check(form,p.optString("name")+"\n"+t("Сейчас: ","Current: ")+(p.optString("current").isEmpty()?t("не установлен","not installed"):p.optString("current"))+" → "+t("Бэкап: ","Backup: ")+p.optString("backup"),false);b.setEnabled(p.optBoolean("selectable"));checks.add(b);}action(form,t("Выбрать все доступные различия","Select all available differences"),()->{if(checks.stream().filter(View::isEnabled).count()>200){message(t("За один план можно выбрать до 200 пакетов. Выберите их вручную несколькими группами.","Select up to 200 packages per plan. Process larger lists in batches."));return;}for(CheckBox b:checks)if(b.isEnabled())b.setChecked(true);});action(form,t("Не заменять ничего","Do not replace anything"),()->{for(CheckBox b:checks)b.setChecked(false);});WorkspaceDialogs.builder(activity).setTitle(t("Пакеты · различия","Packages · differences")).setView(scroll(form)).setPositiveButton(t("Получить план APT","Get APT plan"),(d,w)->{try{JSONObject packages=new JSONObject();for(int i=0;i<checks.size();i++)if(checks.get(i).isChecked()){JSONObject p=rows.getJSONObject(i);packages.put(p.getString("name"),p.getString("backup"));}if(packages.length()==0)return;run(request("apt-plan").put("packages",packages),plan->{LinearLayout body=column();info(body,plan.optString("plan"));info(body,t("Установка затронет общую среду Termux. Завершите важные задачи. Откроется отдельный терминал; APT дополнительно запросит подтверждение. Старый план может измениться — проверьте его ещё раз в терминале.","Installation changes the shared Termux environment. Finish important jobs. A separate terminal opens; APT asks for confirmation again. Its plan may have changed; review it again in the terminal."));AlertDialog.Builder prompt=WorkspaceDialogs.builder(activity).setTitle(t("План APT","APT plan")).setView(scroll(body)).setNegativeButton(WorkspaceText.tr("Отмена"),null);if(plan.optBoolean("ok"))prompt.setPositiveButton(t("Подтвердить установку","Confirm installation"),(x,y)->packageInstall.accept(plan.optString("command")));prompt.show();});}catch(Exception e){message(errorText("APT_PLAN_FAILED"));}}).setNegativeButton(WorkspaceText.tr("Отмена"),null).show();}
}
